namespace ghidra.framework.main.projectdata.actions;



using docking.action;
using docking.action;
using docking.widgets.tree;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatree;

public class ProjectDataCollapseAction<T> : ContextSpecificAction<T> where T : ProjectTreeContext {

	public ProjectDataCollapseAction(string owner, string group, Class<T> contextClass) : base("Collapse All", owner, contextClass)
    {
		setPopupMenuData(new MenuData(new string[] { "Collapse All" }, group));
		markHelpUnnecessary();
	}

	/* @Override */
	protected void actionPerformed(T context) {
		DataTree tree = context.getTree();
		TreePath[] paths = context.getSelectionPaths();
		collapse(tree, paths[0]);
	}

	/* @Override */
	protected bool isEnabledForContext(T context) {
		if (!context.hasExactlyOneFileOrFolder()) {
			return false;
		}
		TreePath[] paths = context.getSelectionPaths();
		GTreeNode node = (GTreeNode) paths[0].getLastPathComponent();
		if (node is DomainFolderNode folderNode) {
			return folderNode.isLoaded();
		}
		if (node is DomainFileNode fileNode) {
			return fileNode.isFolderLink() && !fileNode.isLeaf() && fileNode.isLoaded();
		}
		return false;
	}

	/**
	 * Expand the first selected node; called from an action listener
	 * on a menu.
	 */
	private void collapse(DataTree tree, TreePath path) {
		tree.collapseAll((GTreeNode) path.getLastPathComponent());
	}
}
